        	Set<String> dupCheck = new HashSet<String>();
        	for(String hdr : header) {
        		if (!dupCheck.add(hdr)) {
        			throw new IllegalArgumentException("The header contains a duplicate entry: '" + hdr + "' in " + Arrays.toString(header));
